+        &self,
+        endpoint: &SshEndpoint,
+        profile: &SshForwardProfile,
+        trust: &StoredTrust,
+    ) -> Result<SshSession, SshTransportError> {
+        let permit = self
+            .handshake_gate
+            .acquire()
+            .await
+            .map_err(|_| SshTransportError::Connect)?;
+        let result = SshSession::connect(endpoint, &profile.ssh_user, &profile.auth, trust).await;
+        drop(permit);
+        result
